module mlp (
  input clk,
  input rst_n,
  input load_valid,
  input signed [7:0] load_data,
  input start,
  input [12:0] depth1,
  input [12:0] cols1,
  input [12:0] cols2,
  input [17:0] scale1,
  input [6:0] shift1,
  input [17:0] scale2,
  input [6:0] shift2,
  output [12:0] w_addr,
  input signed [7:0] w_data,
  output o_valid,
  output [5:0] o_index,
  output signed [7:0] o_data,
  output busy
);

  reg signed [7:0] act [0:127];

  reg [5:0] load_idx;
  always @(posedge clk) begin
    if (!rst_n)
      load_idx <= 0;
    else if (load_valid)
      load_idx <= load_idx + 1;
  end

  always @(posedge clk) begin
    if (load_valid)
      act[load_idx] <= load_data;
  end

  reg [1:0] state;
  localparam IDLE = 2'b00, MATMUL1 = 2'b01, MATMUL2 = 2'b10;

  wire [12:0] a_addr1, w_addr1;
  wire mac_valid1, col_valid1, mac_clear1;
  wire [5:0] col_index1;

  matvec matvec1 (
    .clk(clk),
    .rst_n(rst_n),
    .start(state == IDLE && start),
    .depth(depth1),
    .cols(cols1),
    .a_addr(a_addr1),
    .w_addr(w_addr1),
    .mac_valid(mac_valid1),
    .col_valid(col_valid1),
    .col_index(col_index1),
    .mac_clear(mac_clear1)
  );

  wire [12:0] a_addr2, w_addr2;
  wire mac_valid2, col_valid2, mac_clear2;
  wire [5:0] col_index2;

  matvec matvec2 (
    .clk(clk),
    .rst_n(rst_n),
    .start(state == MATMUL1 && count_req1 == cols1 && !requant1_valid_out),
    .depth(cols1),
    .cols(cols2),
    .a_addr(a_addr2),
    .w_addr(w_addr2),
    .mac_valid(mac_valid2),
    .col_valid(col_valid2),
    .col_index(col_index2),
    .mac_clear(mac_clear2)
  );

  wire [12:0] a_addr_sel = (state == MATMUL1) ? a_addr1 : a_addr2;
  wire [12:0] w_addr_raw = (state == MATMUL1) ? w_addr1 : w_addr2;
  assign w_addr = w_addr_raw + ((state == MATMUL1) ? 13'b0 : (depth1 * cols1));

  wire mac_valid_sel = (state == MATMUL1) ? mac_valid1 : mac_valid2;
  wire mac_clear_sel = (state == MATMUL1) ? mac_clear1 : mac_clear2;

  reg signed [7:0] a_data;
  always @(posedge clk) begin
    if (state == MATMUL1)
      a_data <= act[a_addr1];
    else
      a_data <= act[64 + a_addr2];
  end

  wire [28:0] mac_acc;
  wire mac_valid_out;

  mac mac_inst (
    .clk(clk),
    .rst_n(rst_n),
    .clear(mac_clear_sel),
    .a(a_data),
    .b(w_data),
    .valid_in(mac_valid_sel),
    .acc(mac_acc),
    .valid_out(mac_valid_out)
  );

  wire requant1_valid_in = (state == MATMUL1) ? col_valid1 : 1'b0;
  wire signed [7:0] requant1_q_out;
  wire requant1_valid_out;

  requant requant1_inst (
    .clk(clk),
    .rst_n(rst_n),
    .acc_in(mac_acc),
    .scale(scale1),
    .shift(shift1),
    .valid_in(requant1_valid_in),
    .q_out(requant1_q_out),
    .sat(),
    .valid_out(requant1_valid_out)
  );

  wire requant2_valid_in = (state == MATMUL2) ? col_valid2 : 1'b0;
  wire signed [7:0] requant2_q_out;
  wire requant2_valid_out;

  requant requant2_inst (
    .clk(clk),
    .rst_n(rst_n),
    .acc_in(mac_acc),
    .scale(scale2),
    .shift(shift2),
    .valid_in(requant2_valid_in),
    .q_out(requant2_q_out),
    .sat(),
    .valid_out(requant2_valid_out)
  );

  reg [12:0] count_req1;
  always @(posedge clk) begin
    if (!rst_n || state != MATMUL1)
      count_req1 <= 0;
    else if (requant1_valid_out)
      count_req1 <= count_req1 + 1;
  end

  reg [5:0] col_index_delay1 [0:8];
  always @(posedge clk) begin
    if (col_valid1)
      col_index_delay1[0] <= col_index1;
    col_index_delay1[1] <= col_index_delay1[0];
    col_index_delay1[2] <= col_index_delay1[1];
    col_index_delay1[3] <= col_index_delay1[2];
    col_index_delay1[4] <= col_index_delay1[3];
    col_index_delay1[5] <= col_index_delay1[4];
    col_index_delay1[6] <= col_index_delay1[5];
    col_index_delay1[7] <= col_index_delay1[6];
    col_index_delay1[8] <= col_index_delay1[7];
  end

  always @(posedge clk) begin
    if (requant1_valid_out) begin
      if (requant1_q_out[7])
        act[64 + col_index_delay1[8]] <= 8'b0;
      else
        act[64 + col_index_delay1[8]] <= requant1_q_out;
    end
  end

  reg [12:0] count_req2;
  always @(posedge clk) begin
    if (!rst_n || state != MATMUL2)
      count_req2 <= 0;
    else if (requant2_valid_out)
      count_req2 <= count_req2 + 1;
  end

  reg [5:0] col_index_delay2 [0:8];
  always @(posedge clk) begin
    if (col_valid2)
      col_index_delay2[0] <= col_index2;
    col_index_delay2[1] <= col_index_delay2[0];
    col_index_delay2[2] <= col_index_delay2[1];
    col_index_delay2[3] <= col_index_delay2[2];
    col_index_delay2[4] <= col_index_delay2[3];
    col_index_delay2[5] <= col_index_delay2[4];
    col_index_delay2[6] <= col_index_delay2[5];
    col_index_delay2[7] <= col_index_delay2[6];
    col_index_delay2[8] <= col_index_delay2[7];
  end

  assign o_valid = requant2_valid_out;
  assign o_index = col_index_delay2[8];
  assign o_data = requant2_q_out;

  always @(posedge clk) begin
    if (!rst_n)
      state <= IDLE;
    else begin
      case (state)
        IDLE: begin
          if (start)
            state <= MATMUL1;
        end
        MATMUL1: begin
          if (count_req1 == cols1 && !requant1_valid_out)
            state <= MATMUL2;
        end
        MATMUL2: begin
          if (count_req2 == cols2 && !requant2_valid_out)
            state <= IDLE;
        end
      endcase
    end
  end

  assign busy = (state != IDLE);

endmodule

